package com.landportal.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="payments") public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) Compensation compensation; double amount; String transactionReference; @Enumerated(EnumType.STRING) PaymentStatus status; LocalDateTime paidAt; public Long getId(){return id;} public Compensation getCompensation(){return compensation;} public void setCompensation(Compensation v){compensation=v;} public double getAmount(){return amount;} public void setAmount(double v){amount=v;} public String getTransactionReference(){return transactionReference;} public void setTransactionReference(String v){transactionReference=v;} public PaymentStatus getStatus(){return status;} public void setStatus(PaymentStatus v){status=v;} public LocalDateTime getPaidAt(){return paidAt;} public void setPaidAt(LocalDateTime v){paidAt=v;} }
